					if(Array.isArray(skill)){
						for(var i=0;i<skill.length;i++){
							this.addSkill(skill[i]);
						}
					}
					else{
						if(this.skills.contains(skill)) return;
						var info=lib.skill[skill];
						if(!info) return;
						if(!addToSkills){
							this.skills.add(skill);
							if(!nobroadcast){
